// Run with Node 22+ and Chrome; set CHROME_BIN when Chrome is not at the platform default.
const assert = require('node:assert/strict');
const http = require('node:http');
const fs = require('node:fs/promises');
const path = require('node:path');
const {spawn} = require('node:child_process');
const {once} = require('node:events');
const {setTimeout: delay} = require('node:timers/promises');
const root=path.resolve(__dirname,'../static');
const profile=path.join(require('node:os').tmpdir(),'streamanalyzer-rtsp-ui-'+process.pid);
const chromePath=process.env.CHROME_BIN||(process.platform==='darwin'?'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome':process.platform==='win32'?'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe':'google-chrome');
async function until(f){for(let n=0;n<100;n++){const result=await f();if(result)return result;await delay(100);}throw new Error('Timeout');}
(async()=>{
 const server=http.createServer(async(req,res)=>{
  if(req.url.startsWith('/api/')){res.setHeader('Content-Type','application/json');res.end(req.url.endsWith('/config')?'{}':'[]');return;}
  const name=req.url==='/diagnostics'?'diagnostics.html':req.url.replace(/^\/static\//,'');
  try{const body=await fs.readFile(path.join(root,name));res.setHeader('Content-Type',name.endsWith('.js')?'text/javascript':name.endsWith('.css')?'text/css':'text/html');res.end(body);}catch{res.writeHead(404).end();}
 });
 server.listen(0,'127.0.0.1');await once(server,'listening');
 const chrome=spawn(chromePath,['--headless=new','--disable-gpu','--no-first-run',`--user-data-dir=${profile}`,'--remote-debugging-port=0','about:blank'],{stdio:'ignore'});
 let ws;
 try{
  const debug=await until(()=>fs.readFile(path.join(profile,'DevToolsActivePort'),'utf8').catch(()=>''));
  const tabs=await(await fetch(`http://127.0.0.1:${debug.split('\n')[0]}/json/list`)).json();
  ws=new WebSocket(tabs.find(tab=>tab.type==='page').webSocketDebuggerUrl);await once(ws,'open');
  const pending=new Map();let n=0;const errors=[];
  ws.addEventListener('message',({data})=>{const msg=JSON.parse(data);if(msg.id){const item=pending.get(msg.id);pending.delete(msg.id);msg.error?item.reject(msg.error):item.resolve(msg.result);}else if(msg.method==='Runtime.exceptionThrown')errors.push(msg.params);});
  const cdp=(method,params={})=>new Promise((resolve,reject)=>{pending.set(++n,{resolve,reject});ws.send(JSON.stringify({id:n,method,params}));});
  const evaluate=async expression=>{const result=await cdp('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true,replMode:true});if(result.exceptionDetails)throw new Error(JSON.stringify(result.exceptionDetails));return result.result.value;};
  await cdp('Runtime.enable');await cdp('Page.navigate',{url:`http://127.0.0.1:${server.address().port}/diagnostics`});
  await until(()=>evaluate(`typeof renderRequestTiming === 'function'`).catch(()=>false));
  const fixture={id:'rtsp-fixture',protocol:'rtsp',mode:'sample',status:'done',created_at:'2026-11-19T00:00:00Z',origin:'rtsp://camera-user:private-password@camera.example:8554/private-profile?token=private-token',report_ready:true,
   report:{rule_version:'rtsp/1',manifest:{protocol:'rtsp',stream:{bytes:1024,sha256:'fixture'},observation:{started_at:'2026-11-19T00:00:00Z',elapsed_ms:1000,requested_seconds:1,end_reason:'duration_limit',first_payload_ms:0,stages:[{name:'dns',start_ms:0,end_ms:0},{name:'connect',start_ms:0,end_ms:0},{name:'rtsp_describe',start_ms:0,end_ms:0},{name:'rtsp_setup',start_ms:0,end_ms:0},{name:'rtsp_play',start_ms:0,end_ms:0}]}},metrics:{video_frames:0,audio_frames:0},
    rtsp:{boundary:'decrypted_rtsp_application',transport:'tcp_interleaved',secure:false,sdp_available:true,connections:1,rtp_packets:3,rtcp_packets:1,rtp_bytes:130,first_rtp_ms:0,first_video_rtp_ms:0,first_audio_rtp_ms:10,malformed_packets:0,unknown_channel_packets:0,unknown_payload_packets:0,trailing_bytes:0,requests_truncated:2,analysis_limited:true,raw_sdp:'private-sdp-title',url:'rtsp://private-source/path',
     requests:[{number:1,connection_id:1,method:'DESCRIBE',cseq:1,start_ms:0,end_ms:0,status_code:401,complete:true,uri:'rtsp://private-source/path'},{number:2,connection_id:1,method:'DESCRIBE',cseq:2,start_ms:0,end_ms:0,status_code:200,complete:true},{number:3,connection_id:1,method:'SETUP',cseq:3,start_ms:0,end_ms:0,status_code:200,complete:true},{number:4,connection_id:1,method:'PLAY',cseq:4,start_ms:0,end_ms:0,status_code:200,complete:true},{number:5,connection_id:1,method:'GET_PARAMETER',cseq:5,start_ms:20,end_ms:1000,complete:false,failure_code:'timeout'}],
     tracks:[{id:1,media_id:1,kind:'video',codec:'h264',payload_type:96,clock_rate:90000,received:true,rtp_packets:2,rtp_bytes:100,first_rtp_ms:0,last_rtp_ms:0,max_arrival_gap_ms:0,sequence_gaps:1,missing_sequence_packets:2,duplicate_packets:0,out_of_order_packets:1,ssrc_changes:1,sequence_resets:1,timestamp_regressions:1,analysis_limited:true},{id:2,media_id:2,kind:'audio',codec:'pcmu',payload_type:0,clock_rate:8000,channels:1,received:false,rtp_packets:0,rtp_bytes:0,max_arrival_gap_ms:0,sequence_gaps:0,missing_sequence_packets:0,duplicate_packets:0,out_of_order_packets:0,ssrc_changes:0,sequence_resets:0,timestamp_regressions:0},{id:3,media_id:3,kind:'audio',codec:'aac',payload_type:97,clock_rate:48000,channels:2,received:true,rtp_packets:1,rtp_bytes:30,first_rtp_ms:10,last_rtp_ms:10,max_arrival_gap_ms:0,sequence_gaps:0,missing_sequence_packets:0,duplicate_packets:0,out_of_order_packets:0,ssrc_changes:0,sequence_resets:0,timestamp_regressions:0}]},
    findings:[{id:'R001',severity:'warn',message:'核对 RTP 序号',start_ms:0,end_ms:0,evidence:[{kind:'rtp_packet',track:1,codec:'h264',rtp_sequence:0,arrival_ms:0,artifact:'server-wire.bin',offset:100,size:50}]}]},explanation:{provider:'deepseek',summary:'核对接收点证据',hypotheses:[{claim:'序号缺口待验证',evidence_ids:['R001'],next_check:'对照源端输出'}]}};
  await evaluate(`window.rtspFixture=${JSON.stringify(fixture)};window.rtspPosts=[];window.fetch=async(url,options={})=>{let value;if(url.endsWith('/runs')&&options.method==='POST'){const body=JSON.parse(options.body);rtspPosts.push(body);rtspFixture.protocol=body.protocol;rtspFixture.origin=body.url;rtspFixture.report.manifest.protocol=body.protocol;rtspFixture.report.manifest.observation.origin=body.url;rtspFixture.report.rtsp.secure=body.protocol==='rtsps';rtspFixture.report.manifest.observation.stages=rtspFixture.report.manifest.observation.stages.filter(n=>n.name!=='tls');if(body.protocol==='rtsps')rtspFixture.report.manifest.observation.stages.push({name:'tls',start_ms:0,end_ms:0});value={id:rtspFixture.id,protocol:body.protocol,player:{token:'should-not-start',source:'same_capture'}};}else if(url.endsWith('/runs/rtsp-fixture'))value=rtspFixture;else if(url.endsWith('/runs'))value=[rtspFixture];else value={};return new Response(JSON.stringify(value),{status:200,headers:{'Content-Type':'application/json'}});};`);
  for(const protocol of ['rtsp','rtsps']){
   await evaluate(`document.getElementById('analyze-playback').checked=true;document.getElementById('protocol').value='${protocol}';document.getElementById('protocol').dispatchEvent(new Event('change'))`);
   assert.deepEqual(await evaluate(`({disabled:document.getElementById('analyze-playback').disabled,checked:document.getElementById('analyze-playback').checked,hidden:document.getElementById('playback-capability-note').hidden})`),{disabled:true,checked:false,hidden:false});
   assert.match(await evaluate(`document.getElementById('url-hint').textContent`),/TCP.*校验服务端证书/);
   await evaluate(`document.getElementById('url').value='${protocol}://camera-user:private-password@camera.example:8554/private-profile?token=private-token';document.getElementById('seconds').value='1';document.getElementById('analyze-playback').checked=true;document.getElementById('sample').requestSubmit()`);
   await until(()=>evaluate(`rtspPosts.length===${protocol==='rtsp'?1:2}&&!document.querySelector('#sample button[type="submit"]').disabled&&document.getElementById('rtsp-report').hidden===false`));
   assert.equal(await evaluate(`rtspPosts.at(-1).playback`),false);assert.equal(await evaluate(`!!activePlayer`),false);assert.equal(await evaluate(`document.getElementById('player-preview').hidden`),true);
   const state=await evaluate(`({summary:document.getElementById('summary').textContent,history:document.getElementById('runs').textContent,body:document.getElementById('report').textContent,requests:Array.from(document.querySelectorAll('#rtsp-request-table tbody tr')).map(n=>Array.from(n.cells).map(c=>c.textContent)),declared:Array.from(document.querySelectorAll('#rtsp-declared-tracks tbody tr')).map(n=>Array.from(n.cells).map(c=>c.textContent)),received:Array.from(document.querySelectorAll('#rtsp-received-tracks tbody tr')).map(n=>Array.from(n.cells).map(c=>c.textContent)),sequence:Array.from(document.querySelectorAll('#rtsp-sequence-table tbody tr')).map(n=>Array.from(n.cells).map(c=>c.textContent)),evidence:Array.from(document.querySelector('#R001 tbody tr').cells).map(n=>n.textContent),timing:document.getElementById('timing-metrics').textContent,tls:Array.from(document.querySelectorAll('#rtsp-metrics div')).find(n=>n.querySelector('dt').textContent==='TLS 阶段').querySelector('dd').textContent})`);
   assert.equal(state.requests.length,5);assert.equal(state.requests[0][4],'401');assert.equal(state.requests[1][4],'200');assert.equal(state.requests[0][7],'0 ms');assert.equal(state.requests[4][4],'未收到响应');assert.equal(state.requests[4][7],'980 ms');assert.match(state.requests[4][9],/超时 \[timeout\]/);
   assert.deepEqual(state.declared[1],['#2','2','音频','pcmu','0','8000 Hz','1']);assert.deepEqual(state.received[0].slice(0,7),['#1','已收到 RTP','2','100','0 ms','0 ms','0 ms']);assert.deepEqual(state.received[1].slice(0,7),['#2','未收到对应 RTP','0','0','未观测','未观测','未观测']);assert.equal(state.received[2][6],'未观测');assert.deepEqual(state.sequence[1],['#2',...Array(7).fill('未观测')]);assert.deepEqual(state.evidence,['RTP 包','#1','h264','0','0','server-wire.bin','100','50']);
   assert.match(state.timing,/首个有效 RTP 包0 ms/);assert.match(state.timing,/首个视频 RTP 到达0 ms/);assert.equal(state.tls,protocol==='rtsps'?'0 ms':'不适用（RTSP）');assert.match(state.body,/序号跳变\/重置候选/);assert.match(state.body,/B 帧或乱序/);assert.match(state.body,/分析上限/);assert.match(state.body,/另有 2 条控制请求/);
   for(const secret of ['camera-user','private-password','private-profile','private-token','private-sdp-title','private-source']){assert.ok(!state.body.includes(secret));assert.ok(!state.summary.includes(secret));assert.ok(!state.history.includes(secret));}
   assert.equal(await evaluate(`document.getElementById('player-report').hidden`),true);assert.match(await evaluate(`document.getElementById('dump').textContent`),/RTSP\/RTP ZIP/);assert.match(await evaluate(`document.getElementById('bundle').getAttribute('href')`),/rtsp-fixture\/evidence.zip$/);
   await evaluate(`document.querySelector('#explanation a').click()`);assert.equal(await evaluate(`document.getElementById('R001').open`),true);assert.equal(await evaluate(`Array.from(document.querySelectorAll('[id]')).length===new Set(Array.from(document.querySelectorAll('[id]')).map(n=>n.id)).size`),true);
   for(const width of [1440,375]){await cdp('Emulation.setDeviceMetricsOverride',{width,height:1000,deviceScaleFactor:1,mobile:false});await evaluate(`document.querySelector('#rtsp-report details').open=true`);assert.equal(await evaluate(`document.documentElement.scrollWidth>innerWidth`),false,`native table overflow at ${width}`);}
  }
  await evaluate(`window.savedNativeMetrics=rtspFixture.report.rtsp;delete rtspFixture.report.rtsp;renderDetail(rtspFixture)`);assert.match(await evaluate(`document.getElementById('rtsp-report-state').textContent`),/未包含 RTSP/);assert.equal(await evaluate(`document.querySelectorAll('#rtsp-declared-tracks tbody tr').length`),0);
  await evaluate(`rtspFixture.report.rtsp={...savedNativeMetrics,first_rtp_ms:null,first_video_rtp_ms:null,first_audio_rtp_ms:null,tracks:[],requests:[],sdp_available:false};renderDetail(rtspFixture)`);assert.match(await evaluate(`document.getElementById('timing-metrics').textContent`),/首个有效 RTP 包未观测/);assert.match(await evaluate(`document.getElementById('rtsp-declared-tracks').textContent`),/未取得可解析 SDP/);
  await evaluate(`document.getElementById('protocol').value='http-flv';document.getElementById('protocol').dispatchEvent(new Event('change'));rtspFixture.protocol='http-flv';rtspFixture.origin='https://example.test/stream.flv';rtspFixture.report.manifest.protocol='http-flv';renderDetail(rtspFixture)`);assert.equal(await evaluate(`document.getElementById('analyze-playback').disabled`),false);assert.equal(await evaluate(`document.getElementById('playback-capability-note').hidden`),true);assert.equal(await evaluate(`document.getElementById('rtsp-report').hidden`),true);
  assert.equal(errors.length,0,JSON.stringify(errors));
  console.log(JSON.stringify({result:'PASS',cases:['RTSP and RTSPS selectors','preview disabled/unchecked and forced false POST','native grant never starts browser playback','SDP declaration versus RTP received counts','payload type zero and first arrival zero','unreceived track sequence stats stay unknown','single packet interarrival stays unknown','control 401/200/timeout timings','native origin and raw metadata privacy','RTP evidence sequence zero and byte offsets','native model evidence anchor','analysis/truncation notices','375/1440px layout','missing metrics and no-RTP capability','switch back restores normal protocol controls']}));
 }finally{ws?.close();chrome.kill('SIGTERM');await once(chrome,'exit').catch(()=>{});server.close();await fs.rm(profile,{recursive:true,force:true,maxRetries:5,retryDelay:100});}
})().catch(err=>{console.error(err);process.exitCode=1;});
